import * as React from "react"
import { cn } from "cn"

import type { WellDesign } from "../data"

type TrajectorySketchProps = React.ComponentProps<"svg"> & {
  design: Pick<WellDesign, "path" | "casings" | "td" | "kickOff" | "md">
  /** Depth labels along the left edge. */
  showLabels?: boolean
}

const W = 240
const H = 200
const PAD = { top: 16, right: 44, bottom: 12, left: 48 }

/**
 * Minimal SVG well-trajectory sketch: a polyline from surface to TD with
 * casing shoes drawn as ticks and depth / hole-size labels.
 */
function TrajectorySketch({
  className,
  design,
  showLabels = true,
  ...props
}: TrajectorySketchProps) {
  const innerW = W - PAD.left - PAD.right
  const innerH = H - PAD.top - PAD.bottom
  const toX = (x: number) => PAD.left + x * innerW
  const toY = (y: number) => PAD.top + y * innerH
  const points = design.path.map(([x, y]) => `${toX(x)},${toY(y)}`).join(" ")

  /** Approximate x on the path at a given normalised depth. */
  const xAtDepth = (depth: number) => {
    const path = design.path
    for (let i = 1; i < path.length; i++) {
      const [x0, y0] = path[i - 1]
      const [x1, y1] = path[i]
      if (depth <= y1) {
        const t = y1 === y0 ? 0 : (depth - y0) / (y1 - y0)
        return x0 + (x1 - x0) * t
      }
    }
    return path[path.length - 1][0]
  }

  const depthFt = (fraction: number) => Math.round(design.td * fraction)

  return (
    <svg
      data-slot="trajectory-sketch"
      viewBox={`0 0 ${W} ${H}`}
      role="img"
      aria-label="Well trajectory sketch"
      className={cn("h-auto w-full max-w-full text-muted-foreground", className)}
      {...props}
    >
      {/* surface line */}
      <line
        x1={PAD.left - 8}
        x2={W - PAD.right + 8}
        y1={PAD.top}
        y2={PAD.top}
        className="stroke-border-strong"
        strokeWidth={2}
      />
      {/* depth grid */}
      {[0.25, 0.5, 0.75].map((fraction) => (
        <line
          key={fraction}
          x1={PAD.left}
          x2={W - PAD.right}
          y1={toY(fraction)}
          y2={toY(fraction)}
          className="stroke-border-subtle"
          strokeDasharray="2 4"
        />
      ))}
      {/* trajectory */}
      <polyline
        points={points}
        fill="none"
        stroke="var(--chart-1)"
        strokeWidth={3}
        strokeLinejoin="round"
        strokeLinecap="round"
      />
      {/* casing shoes */}
      {design.casings.map((casing) => {
        const x = toX(xAtDepth(casing.depth))
        const y = toY(casing.depth)
        return (
          <g key={`${casing.depth}-${casing.size}`}>
            <line
              x1={x - 7}
              x2={x + 7}
              y1={y}
              y2={y}
              stroke="var(--chart-2)"
              strokeWidth={2.5}
              strokeLinecap="round"
            />
            {showLabels && (
              <>
                <text
                  x={PAD.left - 6}
                  y={y + 3}
                  textAnchor="end"
                  className="fill-current font-mono"
                  fontSize={8}
                >
                  {depthFt(casing.depth).toLocaleString()} ft
                </text>
                <text
                  x={W - PAD.right + 6}
                  y={y + 3}
                  textAnchor="start"
                  fill="var(--chart-1)"
                  className="font-mono"
                  fontSize={8}
                >
                  {casing.size}
                </text>
              </>
            )}
          </g>
        )
      })}
      {/* TD marker */}
      <circle
        cx={toX(design.path[design.path.length - 1][0])}
        cy={toY(design.path[design.path.length - 1][1])}
        r={3.5}
        fill="var(--chart-5)"
      />
    </svg>
  )
}

export { TrajectorySketch }
export type { TrajectorySketchProps }

"use client"

import * as React from "react"

import { TrajectorySketch } from "./components/trajectory-sketch"
import { WellDesignCard } from "./components/well-design-card"
import { wellDesigns } from "./data"

/** Route-ready page: a responsive grid of well design cards. */
export default function WellDesignCardPage() {
  const [selected, setSelected] = React.useState<string[]>([])

  return (
    <div
      data-slot="well-design-card-page"
      className="min-h-svh w-full bg-background px-4 py-8 text-foreground md:px-8"
    >
      <div className="mx-auto grid max-w-5xl gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {wellDesigns.map((design) => (
          <WellDesignCard
            key={design.id}
            design={design}
            isSelected={selected.includes(design.id)}
            onSelectedChange={(next) =>
              setSelected((current) =>
                next
                  ? [...current, design.id]
                  : current.filter((id) => id !== design.id)
              )
            }
          />
        ))}
      </div>
    </div>
  )
}

export { WellDesignCard, TrajectorySketch }
export { wellDesigns, trajectoryMeta, phaseMeta, riskLabel } from "./data"
export type { WellDesign, TrajectoryType, DesignPhase } from "./data"
export type { WellDesignCardProps } from "./components/well-design-card"
